{
  "pk": "sf_product",
  "sk": "sf_product",
  "name": "sf_product",
  "data": {
    "name": "sf_product",
    "title": "Store Product",
    "description": "Store Product",
    "type": "Concrete",
    "enablePost": true,
    "enableWorkflow": true,
    "enableVersioning": true,
    "enableIndexing": true,
    "enableSubSchema": true,
    "permission": {},
    "validations": {},
    "schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "label": "Title",
          "group": "name"
        },
        "slug": {
          "type": "string",
          "pattern": "^[a-zA-Z_\\-0-9]*$",
          "default": "{{name}}",
          "transform": [
            "uri",
            "lowercase",
            "suffix-",
            "random-string"
          ],
          "textSearch": true,
          "group": "name"
        },
        "sku": {
          "type": "string",
          "pattern": "^[a-zA-Z_\\-0-9]*$",
          "minLength": 3,
          "maxLength": 50,
          "unique": true,
          "textSearch": true,
          "placeholder": "Made from the name if left blank",
          "group": "slug"
        },
        "price": {
          "type": "number",
          "group": "price"
        },
        "cost": {
          "type": "number",
          "group": "price",
          "hideIn": [
            "public"
          ],
          "description": "Total unit cost \u2014 the sum of costComponents when those are used. Margin is price less this."
        },
        "costComponents": {
          "type": "array",
          "title": "Cost breakdown",
          "hideIn": [
            "public"
          ],
          "collapsible": true,
          "items": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "e.g. purchase, freight in, packaging, handling, prep labour"
              },
              "amount": {
                "type": "number"
              },
              "note": {
                "type": "string"
              }
            }
          },
          "group": "price"
        },
        "tax": {
          "type": "boolean",
          "group": "price"
        },
        "hide": {
          "type": "boolean",
          "x-control-variant": "checkbox",
          "group": "price"
        },
        "tiers": {
          "type": "array",
          "collapsible": true,
          "description": "Pricing tiers (volume discounts, group pricing)",
          "items": {
            "type": "object",
            "properties": {
              "minQuantity": {
                "type": "number",
                "minimum": 1,
                "description": "Minimum quantity for this tier"
              },
              "maxQuantity": {
                "type": "number",
                "description": "Maximum quantity (empty = unlimited)"
              },
              "price": {
                "type": "number",
                "description": "Price per unit at this tier"
              },
              "discountPercent": {
                "type": "number",
                "minimum": 0,
                "maximum": 100,
                "description": "Or % discount from base price"
              },
              "groups": {
                "type": "array",
                "description": "Limit to specific groups (empty = all customers)",
                "x-control": "selectMany",
                "x-control-variant": "chip",
                "dataSource": {
                  "source": "collection",
                  "collection": "customer_group",
                  "value": "name",
                  "label": "name"
                },
                "items": {
                  "type": "string"
                }
              }
            }
          },
          "group": "price"
        },
        "brand": {
          "type": "string",
          "x-control": "selectMany",
          "dataSource": {
            "source": "collection",
            "collection": "sf_brand",
            "value": "name",
            "label": "name"
          },
          "group": "status"
        },
        "plan": {
          "type": "string",
          "x-control": "selectMany",
          "dataSource": {
            "source": "collection",
            "collection": "sf_subscription_plan",
            "value": "name",
            "label": "name"
          },
          "group": "status"
        },
        "status": {
          "type": "string",
          "group": "status",
          "enum": [
            "draft",
            "new",
            "pre-order",
            "available",
            "sold-out",
            "discontinued",
            "not-for-sale"
          ]
        },
        "stock": {
          "type": "number",
          "group": "stock"
        },
        "available": {
          "type": "boolean",
          "group": "stock"
        },
        "isbn": {
          "type": "string",
          "group": "stock"
        },
        "discount": {
          "type": "string",
          "group": "discount"
        },
        "points": {
          "type": "number",
          "group": "discount"
        },
        "download": {
          "type": "string",
          "group": "discount"
        },
        "description": {
          "type": "string",
          "hideLabel": true,
          "x-control": "richtext",
          "textSearch": true
        },
        "sold": {
          "type": "number",
          "hidden": true
        },
        "image": {
          "type": "string",
          "hidden": true
        },
        "images": {
          "type": "array",
          "x-control": "file",
