                  "width": {
                    "type": "number"
                  },
                  "height": {
                    "type": "number"
                  },
                  "size": {
                    "type": "number"
                  },
                  "xs": {
                    "type": "object",
                    "properties": {
                      "path": {
                        "type": "string"
                      },
                      "url": {
                        "type": "string"
                      }
                    }
                  },
                  "sm": {
                    "type": "object",
                    "properties": {
                      "path": {
                        "type": "string"
                      },
                      "url": {
                        "type": "string"
                      }
                    }
                  },
                  "md": {
                    "type": "object",
                    "properties": {
                      "path": {
                        "type": "string"
                      },
                      "url": {
                        "type": "string"
                      }
                    }
                  }
