                            },
                            "xs": {
                              "type": "object",
                              "properties": {
                                "path": {
                                  "type": "string"
                                },
                                "url": {
                                  "type": "string"
                                }
                              }
                            },
                            "sm": {
                              "type": "object",
                              "properties": {
                                "path": {
                                  "type": "string"
                                },
                                "url": {
                                  "type": "string"
                                }
                              }
                            },
                            "md": {
                              "type": "object",
                              "properties": {
                                "path": {
                                  "type": "string"
                                },
                                "url": {
                                  "type": "string"
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  },
                  "zones": {
                    "type": "array",
                    "description": "Where uploaded artwork is placed on this view.",
                    "items": {
                      "type": "object",
                      "layout": "horizontal",
                      "properties": {
                        "attribute": {
                          "type": "string",
                          "description": "Name of the file-type attribute whose upload fills this zone (e.g. \"artwork\").",
                          "x-control": "selectMany",
                          "dataSource": {
                            "source": "collection",
                            "collection": "sf_attribute",
                            "value": "name",
                            "label": "name"
                          }
                        },
                        "label": {
                          "type": "string",
                          "description": "Human label for the zone, e.g. \"Chest logo\"."
                        },
                        "x": {
                          "type": "number",
                          "description": "Left offset, % of image width (0\u2013100)."
                        },
                        "y": {
                          "type": "number",
                          "description": "Top offset, % of image height (0\u2013100)."
                        },
                        "width": {
                          "type": "number",
                          "description": "Zone width, % of image width."
                        },
                        "height": {
                          "type": "number",
                          "description": "Zone height, % of image height."
                        },
                        "rotation": {
                          "type": "number",
                          "description": "Rotation in degrees (default 0)."
                        },
                        "fit": {
                          "type": "string",
                          "enum": [
                            "contain",
                            "cover",
                            "fill"
                          ],
