              "group": "shipping-config"
            },
            "config": {
              "type": "string",
              "description": "Shipping configuration to price this product (empty = the site default)",
              "notes": "Rarely needed. Say what the product is with Ships As instead of pointing it at a rate.",
              "x-control": "selectSingle",
              "dataSource": {
                "source": "collection",
                "collection": "sf_shipping_config",
                "value": "name",
                "label": "title"
              },
              "group": "shipping-config"
            },
            "override": {
              "type": "string",
              "enum": [
                "",
                "free",
                "flat"
              ],
              "description": "Quick override: free shipping or flat rate",
              "group": "shipping-config"
            },
            "flatRate": {
              "type": "number",
              "description": "Flat rate amount (when override is flat)",
              "rules": [
                {
                  "operation": "notEqual",
                  "valueA": "{{override}}",
                  "valueB": "flat",
                  "action": "hide"
                }
              ],
              "group": "shipping-config"
            },
            "currency": {
              "type": "string",
              "default": "USD",
              "group": "shipping-config"
            },
            "boxSizes": {
              "type": "array",
              "title": "Packaging (overrides the configuration)",
              "collapsible": true,
              "items": {
                "type": "object",
                "properties": {
                  "name": {
                    "type": "string",
                    "description": "What to call this box"
                  },
                  "quantity": {
                    "type": "number",
                    "default": 1,
