                  },
                  "length": {
                    "type": "number"
                  },
                  "width": {
                    "type": "number"
                  },
                  "height": {
                    "type": "number"
                  },
                  "dimensionUnit": {
                    "type": "string",
                    "enum": [
                      "in",
                      "cm"
                    ],
                    "default": "in"
                  },
                  "weight": {
                    "type": "number",
